effect.shader:
void main() {
vec2 uv = acLayerNorm;
vec2 center = vec2(centerX, centerY);
float aspect = acLayerSize.x / acLayerSize.y;
vec2 diff = uv - center;
vec2 diffA = vec2(diff.x * aspect, diff.y);
float dist = length(diffA) * radius;
float ripple = sin(dist * frequency - acTime * speed);
ripple *= exp(-decay * dist);
vec2 dirA = diffA / max(length(diffA), 1e-6);
vec2 dirUV = vec2(dirA.x / aspect, dirA.y);
vec2 displacedUV = uv + dirUV * ripple * strength;
vec4 displacedColor = texture2DCv(inputImg.texture, displacedUV);
vec4 originalColor  = texture2DCv(inputImg.texture, uv);
float lRaw = cos(dist * frequency - acTime * speed) * exp(-decay * dist);
float light = max(lRaw, 0.0);
vec2 light2D = normalize(vec2(0.6, 0.8));
float orient = clamp(0.5 + 0.5 * dot(dirUV, light2D), 0.0, 1.0);
light = pow(light, lightSharpness) * pow(orient, lightSharpness) * lightIntensity;
vec3 finalColor = displacedColor.rgb;
finalColor += lightColor.rgb * light;
vec3 mixedColor = mix(originalColor.rgb, finalColor, blend);
gl_FragColor = vec4(mixedColor, displacedColor.a);
}
